//! The three free-standing validators: `is_scheme_valid`, `is_host_valid`,
//! `is_port_valid`.
//!
//! Every rule below was pinned down by sweeping the compiled C++ binary over
//! each byte value 0x01..=0xFF in leading, interior and trailing position, and
//! over lengths from 1 to 4000.

/// Highest port number the C++ `is_port_valid` accepts.
pub const MAX_PORT: i32 = 65535;

/// `true` when `scheme` is a non-empty RFC 3986 scheme: an ASCII letter followed
/// by any number of ASCII alphanumerics, `+`, `-` or `.`.
///
/// Confirmed against the binary: `"a"`, `"HTTP"`, `"a+b"`, `"a-b"`, `"a.b"` and
/// `"a1"` are valid; `""`, `"1a"`, `"+a"`, `"-a"`, `".a"`, `"a_b"`, `"a~b"` and
/// anything containing a byte >= 0x80 are not. There is no length limit.
pub fn is_scheme_valid(scheme: impl AsRef<[u8]>) -> bool {
    let scheme = scheme.as_ref();
    match scheme.split_first() {
        None => false,
        Some((first, rest)) => {
            first.is_ascii_alphabetic()
                && rest
                    .iter()
                    .all(|&c| c.is_ascii_alphanumeric() || matches!(c, b'+' | b'-' | b'.'))
        }
    }
}

/// `true` when `host` is non-empty and made up entirely of ASCII alphanumerics,
/// `.`, `-`, `:`, `[` or `]`.
///
/// The bracket and colon allowances are what let a bare IPv6 literal such as
/// `[::1]` pass. Confirmed invalid: the empty string, `_`, `~`, `+`, `%`, `@`,
/// `\`, space, any control byte, and any byte >= 0x80. There is no length limit
/// and no per-label validation, so `a..b`, `-a`, `a.` and `.` all pass.
///
/// (`:` can never actually reach here through [`crate::url_parser::Url::parse`],
/// which splits the port off at the first `:`, so its treatment is
/// unobservable through `test16`; it is accepted for IPv6's sake.)
pub fn is_host_valid(host: impl AsRef<[u8]>) -> bool {
    let host = host.as_ref();
    !host.is_empty()
        && host
            .iter()
            .all(|&c| c.is_ascii_alphanumeric() || matches!(c, b'.' | b'-' | b':' | b'[' | b']'))
}

/// `true` for `0 ..= 65535`.
///
/// Port 0 really is accepted — `http://example.com:0` prints `1` — which is how
/// we know the "no port" sentinel must be negative rather than zero. See
/// [`crate::url_parser::NO_PORT`].
pub fn is_port_valid(port: i32) -> bool {
    (0..=MAX_PORT).contains(&port)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn scheme_rules() {
        for ok in ["a", "Z", "http", "HTTP", "a1", "a+b", "a-b", "a.b", "x2go"] {
            assert!(is_scheme_valid(ok), "{ok:?} should be valid");
        }
        for bad in ["", "1a", "+a", "-a", ".a", "a_b", "a~b", "a b", "a/b", "a:b"] {
            assert!(!is_scheme_valid(bad), "{bad:?} should be invalid");
        }
        assert!(!is_scheme_valid([b'a', 0xC3, 0xA9]));
    }

    #[test]
    fn host_rules() {
        for ok in [
            "a", "0", "example.com", "EXAMPLE.COM", "-example.com", "example..com",
            "example.com.", ".", "..", "-", "1.2.3.4", "[::1]", "[", "]", "[]",
        ] {
            assert!(is_host_valid(ok), "{ok:?} should be valid");
        }
        for bad in ["", "exa_mple.com", "ex ample.com", "a~b", "a+b", "a%b", "a@b", "a\\b", "a\nb"] {
            assert!(!is_host_valid(bad), "{bad:?} should be invalid");
        }
        assert!(!is_host_valid([b'a', 0xFF]));
    }

    #[test]
    fn port_rules() {
        assert!(is_port_valid(0));
        assert!(is_port_valid(1));
        assert!(is_port_valid(65535));
        assert!(!is_port_valid(65536));
        assert!(!is_port_valid(-1));
        assert!(!is_port_valid(i32::MIN));
        assert!(!is_port_valid(i32::MAX));
    }
}

