pub fn is_port_valid(port: i32) -> bool {
    (0..=MAX_PORT).contains(&port)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn scheme_rules() {
        for ok in ["a", "Z", "http", "HTTP", "a1", "a+b", "a-b", "a.b", "x2go"] {
            assert!(is_scheme_valid(ok), "{ok:?} should be valid");
        }
        for bad in ["", "1a", "+a", "-a", ".a", "a_b", "a~b", "a b", "a/b", "a:b"] {
            assert!(!is_scheme_valid(bad), "{bad:?} should be invalid");
        }
        assert!(!is_scheme_valid([b'a', 0xC3, 0xA9]));
    }

    #[test]
    fn host_rules() {
        for ok in [
            "a", "0", "example.com", "EXAMPLE.COM", "-example.com", "example..com",
            "example.com.", ".", "..", "-", "1.2.3.4", "[::1]", "[", "]", "[]",
        ] {
            assert!(is_host_valid(ok), "{ok:?} should be valid");
        }
        for bad in ["", "exa_mple.com", "ex ample.com", "a~b", "a+b", "a%b", "a@b", "a\\b", "a\nb"] {
            assert!(!is_host_valid(bad), "{bad:?} should be invalid");
        }
        assert!(!is_host_valid([b'a', 0xFF]));
    }

    #[test]
    fn port_rules() {
        assert!(is_port_valid(0));
        assert!(is_port_valid(1));
        assert!(is_port_valid(65535));
        assert!(!is_port_valid(65536));
        assert!(!is_port_valid(-1));
        assert!(!is_port_valid(i32::MIN));
        assert!(!is_port_valid(i32::MAX));
    }
}

