//! `split_path`: turn a path into its non-empty `/`-separated segments.

/// Splits `path` on `/` and returns every non-empty piece, in order.
///
/// Verified against the binary:
///
/// * leading, trailing and repeated separators contribute nothing, so
///   `"/a/b/c"`, `"/a/b/c/"` and `"//a//b//c//"` all yield `[a, b, c]`;
/// * `""`, `"/"`, `"//"` and `"///"` all yield zero segments;
/// * a relative path keeps its first piece: `"a/b"` yields `[a, b]`;
/// * segments are **not** percent-decoded — `"a%20b"` stays `"a%20b"` and
///   `"%2F"` is not treated as a separator;
/// * `.` and `..` are ordinary segments, no dot-segment removal happens;
/// * segments are **not** trimmed, so a segment of a single space survives as
///   `" "`, and bytes (including `\n` and anything >= 0x80) pass through
///   untouched.
pub fn split_path(path: impl AsRef<[u8]>) -> Vec<Vec<u8>> {
    path.as_ref()
        .split(|&c| c == b'/')
        .filter(|segment| !segment.is_empty())
        .map(<[u8]>::to_vec)
        .collect()
}

/// Rejoins segments with `/` and a leading `/`, the inverse used by
/// `normalize_path`. Not exercised by `test16`.
pub fn join_path(segments: &[Vec<u8>]) -> Vec<u8> {
    let mut out = Vec::new();
    for segment in segments {
        out.push(b'/');
        out.extend_from_slice(segment);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn seg(path: &str) -> Vec<String> {
        split_path(path)
            .into_iter()
            .map(|s| String::from_utf8(s).unwrap())
            .collect()
    }

    #[test]
    fn separators_collapse() {
        assert_eq!(seg("/a/b/c"), ["a", "b", "c"]);
        assert_eq!(seg("/a/b/c/"), ["a", "b", "c"]);
        assert_eq!(seg("//a//b//c//"), ["a", "b", "c"]);
        assert_eq!(seg("a/b"), ["a", "b"]);
    }

    #[test]
    fn empty_results() {
        assert!(seg("").is_empty());
        assert!(seg("/").is_empty());
        assert!(seg("//").is_empty());
        assert!(seg("///").is_empty());
    }

    #[test]
    fn no_decoding_no_trimming_no_dot_removal() {
        assert_eq!(seg("/a%20b/c%2Fd"), ["a%20b", "c%2Fd"]);
        assert_eq!(seg("/%41"), ["%41"]);
        assert_eq!(seg("/./../a"), [".", "..", "a"]);
        assert_eq!(seg(" /a/b "), [" ", "a", "b "]);
        assert_eq!(seg("/ /"), [" "]);
        assert_eq!(seg("/a\tb/"), ["a\tb"]);
    }

    #[test]
    fn round_trips_through_join() {
        assert_eq!(join_path(&split_path("//a//b/")), b"/a/b");
    }
}

