//! Percent-encoding helpers (`url_encode` / `url_decode`).
//!
//! `test16` never reaches these — `split_path` hands segments back verbatim, as
//! `http://example.com/a%20b/c%2Fd` yielding `["a%20b", "c%2Fd"]` proves — so the
//! exact behaviour here is unobservable and follows RFC 3986.

use super::util::{hex_to_char, is_hex};

/// RFC 3986 unreserved set: `ALPHA / DIGIT / "-" / "." / "_" / "~"`.
#[inline]
fn is_unreserved(c: u8) -> bool {
    c.is_ascii_alphanumeric() || matches!(c, b'-' | b'.' | b'_' | b'~')
}

/// Percent-encodes every byte outside the unreserved set using uppercase hex.
pub fn url_encode(input: impl AsRef<[u8]>) -> Vec<u8> {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let input = input.as_ref();
    let mut out = Vec::with_capacity(input.len());
    for &c in input {
        if is_unreserved(c) {
            out.push(c);
        } else {
            out.push(b'%');
            out.push(HEX[usize::from(c >> 4)]);
            out.push(HEX[usize::from(c & 0x0F)]);
        }
    }
    out
}

/// Decodes `%XX` escapes. A `%` that is not followed by two hex digits is left
/// alone rather than treated as an error.
pub fn url_decode(input: impl AsRef<[u8]>) -> Vec<u8> {
    let input = input.as_ref();
    let mut out = Vec::with_capacity(input.len());
    let mut i = 0;
    while i < input.len() {
        if input[i] == b'%' && i + 2 < input.len() && is_hex(input[i + 1]) && is_hex(input[i + 2]) {
            let hi = hex_to_char(input[i + 1]).unwrap();
            let lo = hex_to_char(input[i + 2]).unwrap();
            out.push((hi << 4) | lo);
            i += 3;
        } else {
            out.push(input[i]);
            i += 1;
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn encodes_reserved_bytes() {
        assert_eq!(url_encode("a b"), b"a%20b");
        assert_eq!(url_encode("a/b"), b"a%2Fb");
        assert_eq!(url_encode("-._~aZ0"), b"-._~aZ0");
    }

    #[test]
    fn decodes_escapes() {
        assert_eq!(url_decode("a%20b"), b"a b");
        assert_eq!(url_decode("%41%42"), b"AB");
        assert_eq!(url_decode("%2f"), b"/");
        assert_eq!(url_decode("100%"), b"100%");
        assert_eq!(url_decode("%zz"), b"%zz");
        assert_eq!(url_decode("%4"), b"%4");
    }

    #[test]
    fn round_trip() {
        let raw: Vec<u8> = (0u8..=255).collect();
        assert_eq!(url_decode(url_encode(&raw)), raw);
    }
}

