//! The `Url` type: the port of C++ `url_parser::URL`.
//!
//! The decomposition in [`Url::parse`] is the heart of the library and every
//! step below is pinned by a probe of the compiled binary; the probes that
//! establish each one are cited inline.

use super::encoding::{url_decode, url_encode};
use super::path::{join_path, split_path};
use super::util::{find_bytes, stoi, to_lower};
use super::NO_PORT;

/// A parsed URL, held as raw bytes so that any argument the C++ program accepts
/// round-trips unchanged (command-line arguments are not required to be UTF-8).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Url {
    scheme: Vec<u8>,
    userinfo: Vec<u8>,
    host: Vec<u8>,
    port: i32,
    path: Vec<u8>,
    query: Vec<u8>,
    fragment: Vec<u8>,
}

impl Default for Url {
    /// Matches the C++ default constructor: all components empty and the port
    /// set to the [`NO_PORT`] sentinel.
    fn default() -> Self {
        Url {
            scheme: Vec::new(),
            userinfo: Vec::new(),
            host: Vec::new(),
            port: NO_PORT,
            path: Vec::new(),
            query: Vec::new(),
            fragment: Vec::new(),
        }
    }
}

impl Url {
    /// `URL::URL()`.
    pub fn new_empty() -> Self {
        Self::default()
    }

    /// `URL::URL(const std::string&)` — construct and parse in one step.
    pub fn new(url: impl AsRef<[u8]>) -> Self {
        let mut parsed = Self::default();
        parsed.parse(url);
        parsed
    }

    /// `URL::from_components(scheme, host, port, path, query, fragment)`.
    pub fn from_components(
        scheme: impl AsRef<[u8]>,
        host: impl AsRef<[u8]>,
        port: i32,
        path: impl AsRef<[u8]>,
        query: impl AsRef<[u8]>,
        fragment: impl AsRef<[u8]>,
    ) -> Self {
        Url {
            scheme: scheme.as_ref().to_vec(),
            userinfo: Vec::new(),
            host: host.as_ref().to_vec(),
            port,
            path: path.as_ref().to_vec(),
            query: query.as_ref().to_vec(),
            fragment: fragment.as_ref().to_vec(),
        }
    }

    /// `URL::parse(const std::string&)`.
    ///
    /// The input is consumed strictly right-to-left by delimiter, and — this is
    /// the part that trips up a from-memory RFC implementation — the fragment
    /// and query are stripped from the **whole** string *before* the scheme is
    /// looked for. Hence `"a?b://c"` has no scheme at all and a path of `"a"`,
    /// which the binary confirms (`1 0 0 0 1 a`).
    ///
    /// Steps:
    ///
    /// 1. split off `fragment` at the first `#`;
    /// 2. split off `query` at the first `?`;
    /// 3. find the first `"://"`. If there is none, everything left is the
    ///    `path` and there is no authority — `"example.com"` parses to a path,
    ///    not a host. Otherwise the text before it is the `scheme` (possibly
    ///    empty, as in `"://example.com"`) and what follows is the authority
    ///    plus path;
    /// 4. the authority runs up to the first `/`; the remainder, `/` included,
    ///    is the `path`;
    /// 5. split off `userinfo` at the **first** `@` of the authority — proven by
    ///    `"http://u@a@b/x"`, whose host is the invalid `"a@b"` rather than `"b"`;
    /// 6. split the port off at the **first** `:` of what remains — proven by
    ///    `"http://[::1]:8080/x"`, which reports an *invalid* port because the
    ///    host became `"["` and the port text `":1]:8080"`, and by
    ///    `"http://a::80/x"`, likewise invalid. The port text goes through
    ///    [`stoi`], falling back to [`NO_PORT`] when that throws.
    ///
    /// No trimming and no case folding happen anywhere: `"HTTP://EXAMPLE.COM/A/B"`
    /// keeps its case and `"x://a "` keeps the space that makes its host invalid.
    pub fn parse(&mut self, url: impl AsRef<[u8]>) {
        let url = url.as_ref();
        *self = Self::default();

        let mut rest = url;

        if let Some(hash) = rest.iter().position(|&c| c == b'#') {
            self.fragment = rest[hash + 1..].to_vec();
            rest = &rest[..hash];
        }

        if let Some(question) = rest.iter().position(|&c| c == b'?') {
            self.query = rest[question + 1..].to_vec();
            rest = &rest[..question];
        }

        let scheme_end = match find_bytes(rest, b"://") {
            Some(pos) => pos,
            None => {
                // No authority section exists at all; the rest is the path.
                self.path = rest.to_vec();
                return;
            }
        };
        self.scheme = rest[..scheme_end].to_vec();
        rest = &rest[scheme_end + 3..];

        let authority_end = rest.iter().position(|&c| c == b'/').unwrap_or(rest.len());
        let mut authority = &rest[..authority_end];
        self.path = rest[authority_end..].to_vec();

        if let Some(at) = authority.iter().position(|&c| c == b'@') {
            self.userinfo = authority[..at].to_vec();
            authority = &authority[at + 1..];
        }

        match authority.iter().position(|&c| c == b':') {
            Some(colon) => {
                self.host = authority[..colon].to_vec();
                self.port = stoi(&authority[colon + 1..]).unwrap_or(NO_PORT);
            }
            None => self.host = authority.to_vec(),
        }
    }

    /// `URL::is_valid_url(const std::string&)` — parse `url` and report
    /// [`Url::is_valid`].
    pub fn is_valid_url(url: impl AsRef<[u8]>) -> bool {
        Url::new(url).is_valid()
    }

    /// `URL::is_valid()` — true when the URL named *something*, i.e. it has a
    /// host or a path.
    ///
    /// A scheme, userinfo, port, query or fragment on its own is not enough,
    /// which is what separates the invalid `"http://"`, `"http://:8080"`,
    /// `"http://@"`, `"http://u@:80"`, `"?x"` and `"://"` from the valid
    /// `"http:///a/b"` (empty host but a path), `"http://@/"` (path `"/"`),
    /// `"://example.com"` (host, empty scheme) and `" "` (path `" "`).
    pub fn is_valid(&self) -> bool {
        !self.host.is_empty() || !self.path.is_empty()
    }

    // ---- component accessors -------------------------------------------------

    pub fn scheme(&self) -> &[u8] {
        &self.scheme
    }

    pub fn userinfo(&self) -> &[u8] {
        &self.userinfo
    }

    pub fn host(&self) -> &[u8] {
        &self.host
    }

    /// The port, or [`NO_PORT`] when the authority carried none (or carried text
    /// `stoi` could not convert).
    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &[u8] {
        &self.path
    }

    pub fn query(&self) -> &[u8] {
        &self.query
    }

    pub fn fragment(&self) -> &[u8] {
        &self.fragment
    }

    /// `URL::authority()` — `[userinfo "@"] host [":" port]`.
    pub fn authority(&self) -> Vec<u8> {
        let mut out = Vec::new();
        if self.has_userinfo() {
            out.extend_from_slice(&self.userinfo);
            out.push(b'@');
        }
        out.extend_from_slice(&self.host);
        if self.has_port() {
            out.push(b':');
            out.extend_from_slice(self.port.to_string().as_bytes());
        }
        out
    }

    // ---- presence predicates -------------------------------------------------

    pub fn has_scheme(&self) -> bool {
        !self.scheme.is_empty()
    }

    pub fn has_userinfo(&self) -> bool {
        !self.userinfo.is_empty()
    }

    pub fn has_host(&self) -> bool {
        !self.host.is_empty()
    }

    pub fn has_port(&self) -> bool {
        self.port != NO_PORT
    }

    pub fn has_path(&self) -> bool {
        !self.path.is_empty()
    }

    pub fn has_query(&self) -> bool {
        !self.query.is_empty()
    }

    pub fn has_fragment(&self) -> bool {
        !self.fragment.is_empty()
    }

    pub fn has_authority(&self) -> bool {
        self.has_userinfo() || self.has_host() || self.has_port()
    }

    // ---- mutators ------------------------------------------------------------

    pub fn set_scheme(&mut self, scheme: impl AsRef<[u8]>) {
        self.scheme = scheme.as_ref().to_vec();
    }

    pub fn set_host(&mut self, host: impl AsRef<[u8]>) {
        self.host = host.as_ref().to_vec();
    }

    pub fn set_port(&mut self, port: i32) {
        self.port = port;
    }

    pub fn set_path(&mut self, path: impl AsRef<[u8]>) {
        self.path = path.as_ref().to_vec();
    }

    pub fn set_query(&mut self, query: impl AsRef<[u8]>) {
        self.query = query.as_ref().to_vec();
    }

    pub fn set_fragment(&mut self, fragment: impl AsRef<[u8]>) {
        self.fragment = fragment.as_ref().to_vec();
    }

    // ---- query parameters ----------------------------------------------------

    /// `URL::parse_query_params()` — split the query on `&`, then each pair on
    /// its first `=`, percent-decoding both halves. Unobservable through
    /// `test16`; RFC-conventional.
    pub fn parse_query_params(&self) -> Vec<(Vec<u8>, Vec<u8>)> {
        self.query
            .split(|&c| c == b'&')
            .filter(|pair| !pair.is_empty())
            .map(|pair| match pair.iter().position(|&c| c == b'=') {
                Some(eq) => (url_decode(&pair[..eq]), url_decode(&pair[eq + 1..])),
                None => (url_decode(pair), Vec::new()),
            })
            .collect()
    }

    /// `URL::query_params()`.
    pub fn query_params(&self) -> Vec<(Vec<u8>, Vec<u8>)> {
        self.parse_query_params()
    }

    /// `URL::get_query_param(key)` — the first value bound to `key`.
    pub fn get_query_param(&self, key: impl AsRef<[u8]>) -> Option<Vec<u8>> {
        let key = key.as_ref();
        self.parse_query_params()
            .into_iter()
            .find(|(k, _)| k == key)
            .map(|(_, v)| v)
    }

    /// `URL::add_query_param(key, value)` — append an encoded `key=value`.
    pub fn add_query_param(&mut self, key: impl AsRef<[u8]>, value: impl AsRef<[u8]>) {
        if !self.query.is_empty() {
            self.query.push(b'&');
        }
        self.query.extend_from_slice(&url_encode(key));
        self.query.push(b'=');
        self.query.extend_from_slice(&url_encode(value));
    }

    /// `URL::remove_query_param(key)` — drop every binding of `key`.
    pub fn remove_query_param(&mut self, key: impl AsRef<[u8]>) {
        let key = key.as_ref();
        let kept: Vec<(Vec<u8>, Vec<u8>)> = self
            .parse_query_params()
            .into_iter()
            .filter(|(k, _)| k != key)
            .collect();
        self.query.clear();
        for (k, v) in kept {
            self.add_query_param(k, v);
        }
    }

    // ---- normalisation -------------------------------------------------------

    /// `URL::normalize_case()` — lowercase the scheme and host only. Note that
    /// `parse` deliberately does *not* do this.
    pub fn normalize_case(&mut self) {
        self.scheme = to_lower(&self.scheme);
        self.host = to_lower(&self.host);
    }

    /// `URL::normalize_path()` — resolve `.` and `..` segments and rebuild the
    /// path with a single leading `/`.
    pub fn normalize_path(&mut self) {
        let mut resolved: Vec<Vec<u8>> = Vec::new();
        for segment in split_path(&self.path) {
            match segment.as_slice() {
                b"." => {}
                b".." => {
                    resolved.pop();
                }
                _ => resolved.push(segment),
            }
        }
        self.path = join_path(&resolved);
    }

    /// `URL::normalize_query()` — re-emit the parameters sorted by key.
    pub fn normalize_query(&mut self) {
        let mut params = self.parse_query_params();
        params.sort();
        self.query.clear();
        for (k, v) in params {
            self.add_query_param(k, v);
        }
    }

    /// `URL::normalize()`.
    pub fn normalize(&mut self) {
        self.normalize_case();
        self.normalize_path();
        self.normalize_query();
    }

    /// `URL::to_string()` — reassemble the components.
    pub fn to_url_string(&self) -> Vec<u8> {
        let mut out = Vec::new();
        if self.has_scheme() {
            out.extend_from_slice(&self.scheme);
            out.extend_from_slice(b"://");
        }
        out.extend_from_slice(&self.authority());
        out.extend_from_slice(&self.path);
        if self.has_query() {
            out.push(b'?');
            out.extend_from_slice(&self.query);
        }
        if self.has_fragment() {
            out.push(b'#');
            out.extend_from_slice(&self.fragment);
        }
        out
    }
}

