/// Index of the first occurrence of `needle` in `haystack`, i.e. the byte-slice
/// equivalent of `std::string::find`.
pub fn find_bytes(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() {
        return Some(0);
    }
