toolUseResult.originalFile:
//! Small helpers mirroring the C++ library's internal statics
//! (`trim`, `to_lower`, `is_hex`, `hex_to_char`) plus a faithful `std::stoi`.

/// Characters the C++ `trim` treats as whitespace, matching the literal set a
/// `find_first_not_of` / `find_last_not_of` pair is conventionally given.
pub const WHITESPACE: &[u8] = b" \t\n\r\x0b\x0c";

/// Bytes `std::isspace` reports as space in the default "C" locale. `strtol`
/// (and therefore `std::stoi`) skips a prefix of these.
#[inline]
pub fn is_space(c: u8) -> bool {
    matches!(c, b' ' | b'\t' | b'\n' | b'\x0b' | b'\x0c' | b'\r')
}

/// Strips leading and trailing [`WHITESPACE`].
///
/// Note: probing shows `parse` does *not* trim its input, nor does `split_path`
/// trim its segments, so this never affects the observable output of `test16`.
pub fn trim(s: &[u8]) -> &[u8] {
    let start = match s.iter().position(|c| !WHITESPACE.contains(c)) {
        Some(i) => i,
        None => return &[],
    };
    let end = s.iter().rposition(|c| !WHITESPACE.contains(c)).unwrap();
    &s[start..=end]
}

/// ASCII-only lowercasing. The C++ version is a `std::transform` over a lambda
/// taking `unsigned char`, so bytes >= 0x80 are left untouched in the "C" locale.
pub fn to_lower(s: &[u8]) -> Vec<u8> {
    s.iter().map(|c| c.to_ascii_lowercase()).collect()
}

/// ASCII-only uppercasing, used when percent-encoding.
pub fn to_upper(s: &[u8]) -> Vec<u8> {
    s.iter().map(|c| c.to_ascii_uppercase()).collect()
}

#[inline]
pub fn is_hex(c: u8) -> bool {
    c.is_ascii_hexdigit()
}

/// Numeric value of a single hex digit, or `None` if `c` is not one.
#[inline]
pub fn hex_to_char(c: u8) -> Option<u8> {
    match c {
        b'0'..=b'9' => Some(c - b'0'),
        b'a'..=b'f' => Some(c - b'a' + 10),
        b'A'..=b'F' => Some(c - b'A' + 10),
        _ => None,
    }
}

/// Largest magnitude a base-10 `int` conversion can hold (`-2^31`).
const MAX_MAGNITUDE: u64 = 2_147_483_648;

/// `std::stoi(s)` with its exceptions folded into `None`:
///
/// * a prefix of whitespace is skipped,
/// * an optional `+` / `-` sign may follow,
/// * one or more base-10 digits are consumed and any trailing bytes ignored,
/// * no digits at all throws `std::invalid_argument` -> `None`,
/// * a value outside `int` range throws `std::out_of_range` -> `None`.
///
/// Because the base is fixed at 10, `"0x50"` yields `0` and `"1e3"` yields `1`,
/// both of which the binary confirms.
pub fn stoi(s: &[u8]) -> Option<i32> {
    let mut i = 0;
    while i < s.len() && is_space(s[i]) {
        i += 1;
    }

    let mut negative = false;
    if i < s.len() && (s[i] == b'+' || s[i] == b'-') {
        negative = s[i] == b'-';
        i += 1;
    }

    let first_digit = i;
    let mut magnitude: u64 = 0;
    let mut overflowed = false;
    while i < s.len() && s[i].is_ascii_digit() {
        if !overflowed {
            magnitude = magnitude * 10 + u64::from(s[i] - b'0');
            // Once the magnitude passes 2^31 it can only grow, so clamp here and
            // keep scanning digits without risking an overflow of our own.
            if magnitude > MAX_MAGNITUDE {
                overflowed = true;
            }
        }
        i += 1;
    }

    if i == first_digit || overflowed {
        return None;
    }

    let value = if negative {
        -(magnitude as i64)
    } else {
        magnitude as i64
    };
    if value < i64::from(i32::MIN) || value > i64::from(i32::MAX) {
        return None;
    }
    Some(value as i32)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn trim_strips_both_ends() {
        assert_eq!(trim(b"  a b  "), b"a b");
        assert_eq!(trim(b"\t\n\r\x0b\x0c"), b"");
        assert_eq!(trim(b""), b"");
        assert_eq!(trim(b"a"), b"a");
    }

    #[test]
    fn stoi_matches_cpp() {
        assert_eq!(stoi(b"80"), Some(80));
        assert_eq!(stoi(b"80abc"), Some(80));
        assert_eq!(stoi(b" 80"), Some(80));
        assert_eq!(stoi(b"\t80"), Some(80));
        assert_eq!(stoi(b"+80"), Some(80));
        assert_eq!(stoi(b"-0"), Some(0));
        assert_eq!(stoi(b"-1"), Some(-1));
        assert_eq!(stoi(b"007"), Some(7));
        assert_eq!(stoi(b"0x50"), Some(0));
        assert_eq!(stoi(b"1e3"), Some(1));
        assert_eq!(stoi(b"8.0"), Some(8));
        assert_eq!(stoi(b"6 5"), Some(6));
        assert_eq!(stoi(b"2147483647"), Some(2_147_483_647));
        assert_eq!(stoi(b"-2147483648"), Some(-2_147_483_648));
        assert_eq!(stoi(b"2147483648"), None);
        assert_eq!(stoi(b"99999999999999999999"), None);
        assert_eq!(stoi(b""), None);
        assert_eq!(stoi(b" "), None);
        assert_eq!(stoi(b"abc"), None);
        assert_eq!(stoi(b"+"), None);
        assert_eq!(stoi(b"-"), None);
    }

    #[test]
    fn hex_helpers() {
        assert!(is_hex(b'0') && is_hex(b'f') && is_hex(b'F'));
        assert!(!is_hex(b'g'));
        assert_eq!(hex_to_char(b'0'), Some(0));
        assert_eq!(hex_to_char(b'A'), Some(10));
        assert_eq!(hex_to_char(b'f'), Some(15));
        assert_eq!(hex_to_char(b'g'), None);
    }
}

