//! A dependency-free Rust port of the C++ `url_parser` library.
//!
//! The C++ sources were not available; every rule implemented here was derived
//! by probing the compiled binary (`test16_executable`) as a black box and is
//! documented at its definition together with the observation that pins it down.
//!
//! Everything is expressed over `&[u8]` rather than `str`, because a
//! command-line argument is an arbitrary byte string and both `is_host_valid`
//! and `split_path` must treat non-UTF-8 bytes exactly as the C++ `std::string`
//! version does.

pub mod encoding;
pub mod path;
pub mod url;
pub mod util;
pub mod validate;

pub use encoding::{url_decode, url_encode};
pub use path::{join_path, split_path};
pub use url::Url;
pub use validate::{is_host_valid, is_port_valid, is_scheme_valid, MAX_PORT};

/// Value `Url::port()` reports when the authority carries no usable port.
///
/// It has to be negative rather than `0`: `http://example.com:0` reports a
/// *valid* port while `http://example.com` reports an invalid one, so `0` is a
/// real port number and cannot double as the "absent" marker.
pub const NO_PORT: i32 = -1;

