//! Port of `tests/test16.cpp`.
//!
//! Usage: `test16 <url>`; prints, one per line, `is_valid_url`, then
//! `is_scheme_valid(scheme)`, `is_host_valid(host)`, `is_port_valid(port)` as
//! `1`/`0` (`std::cout` renders `bool` that way without `std::boolalpha`), then
//! the number of path segments, then the segments themselves.

mod url_parser;

use std::ffi::OsString;
use std::io::{self, Write};

fn main() {
    // `args_os` is used in place of `args` so that a non-UTF-8 argument is passed
    // through byte-for-byte instead of panicking; the C++ program accepts any
    // bytes `argv` can carry.
    let args: Vec<OsString> = std::env::args_os().collect();
    if args.len() < 2 {
        std::process::exit(1); // `if (argc < 2) return 1;`
    }

    let url = arg_bytes(&args[1]);

    println!("{}", flag(url_parser::Url::is_valid_url(&url)));

    let parser = url_parser::Url::new(&url);

    println!("{}", flag(url_parser::is_scheme_valid(parser.scheme())));
    println!("{}", flag(url_parser::is_host_valid(parser.host())));
    println!("{}", flag(url_parser::is_port_valid(parser.port())));

    let path_segments = url_parser::split_path(parser.path());
    println!("{}", path_segments.len());

    // Segments are echoed as raw bytes, exactly as `std::cout << segment` does.
    let stdout = io::stdout();
    let mut out = stdout.lock();
    for segment in &path_segments {
        let _ = out.write_all(segment);
        let _ = out.write_all(b"\n");
    }
    let _ = out.flush();
}

/// `std::cout << bool` prints `1` or `0`.
fn flag(value: bool) -> u8 {
    u8::from(value)
}

#[cfg(unix)]
fn arg_bytes(arg: &OsString) -> Vec<u8> {
    use std::os::unix::ffi::OsStrExt;
    arg.as_os_str().as_bytes().to_vec()
}

#[cfg(not(unix))]
fn arg_bytes(arg: &OsString) -> Vec<u8> {
    arg.to_string_lossy().into_owned().into_bytes()
}

