//! Differential tester: runs the C++ binary and the Rust port over a large
//! corpus of adversarial URLs and compares raw stdout, stderr and exit code.
//!
//! Build: rustc --edition 2021 -O differ.rs -o differ
//! Run:   ./differ <cpp-bin> <rust-bin> [random-count]

use std::ffi::OsStr;
use std::os::unix::ffi::OsStrExt;
use std::process::Command;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Mutex;

fn run(bin: &str, arg: &[u8]) -> (Vec<u8>, Vec<u8>, i32) {
    let out = Command::new(bin)
        .arg(OsStr::from_bytes(arg))
        .output()
        .expect("spawn failed");
    (
        out.stdout,
        out.stderr,
        out.status.code().unwrap_or(-999),
    )
}

fn esc(b: &[u8]) -> String {
    let mut s = String::new();
    for &c in b {
        match c {
            b'\n' => s.push_str("\\n"),
            b'\r' => s.push_str("\\r"),
            b'\t' => s.push_str("\\t"),
            0x20..=0x7e => s.push(c as char),
            _ => s.push_str(&format!("\\x{c:02x}")),
        }
    }
    s
}

struct Rng(u64);
impl Rng {
    fn next(&mut self) -> u64 {
        // xorshift64*, deterministic so failures are reproducible
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

/// Tokens chosen so that products of them hit every delimiter and validator
/// boundary the parser has.
const TOKENS: &[&str] = &[
    "", "a", "1", "http", "://", ":", "//", "/", "@", "?", "#", ".", "-", "_", "[", "]", ":80",
    ":0", ":65536", ":-1", ":abc", " ", "\t", "%20", "..", "example.com", "+", "~", "\\",
];

/// Templates with `$` standing in for a single injected byte.
const TEMPLATES: &[&str] = &[
    "$",
    "$$",
    "a$b",
    "$http://a/b",
    "http$://a/b",
    "ht$tp://a/b",
    "http://$",
    "http://$a/b",
    "http://a$b/c",
    "http://ab$/c",
    "http://a:$80/x",
    "http://a:8$0/x",
    "http://a:80$/x",
    "http://a/b$c/d",
    "http://a/$/b",
    "http://a?b$c",
    "http://a#b$c",
    "http://u$v@a/b",
    "http://u@a$b/c",
    "$://a",
    "a://$",
    "/a$b/c",
    "$/a/b",
    "a/b/$",
];

fn corpus(random_count: usize) -> Vec<Vec<u8>> {
    let mut out: Vec<Vec<u8>> = Vec::new();

    // 1. Hand-picked regression cases.
    for s in [
        "",
        "http://example.com",
        "https://example.com",
        "http://localhost",
        "https://localhost:8080",
        "http://example.com:80",
        "ftp://example.com:21/pub/file.txt",
        "http://user:pass@example.com:8080/p/q?x=1&y=2#frag",
        "http://[::1]:8080/x",
        "http://[::1]",
        "http:///a/b",
        "http://",
        "http://:8080",
        "://",
        "://example.com",
        ":",
        ":///",
        "example.com",
        "a?b://c",
        "a#b://c",
        "http://a://b",
        "http://u@a@b/x",
        "http://a::80/x",
        "http://a:80:90",
        "http://@",
        "http://@/",
        "http://u@:80",
        "HTTP://EXAMPLE.COM/A/B",
        "http://example.com//a//b",
        "http://example.com/./../a",
        "http://example.com/a%20b/c%2Fd",
        "http://a: 80",
        "http://a:+80",
        "http://a:-0",
        "http://a:0x50",
        "http://a:2147483648",
        "http://a:99999999999999999999",
        "http://a:65535x",
        "http://a:65536x",
    ] {
        out.push(s.as_bytes().to_vec());
    }

    // 2. Every byte value injected into every template position.
    for t in TEMPLATES {
        for byte in 1u8..=255 {
            let mut s = Vec::new();
            for c in t.bytes() {
                if c == b'$' {
                    s.push(byte);
                } else {
                    s.push(c);
                }
            }
            out.push(s);
        }
    }

    // 3. Exhaustive products of TOKENS up to length 3.
    for a in TOKENS {
        out.push(a.as_bytes().to_vec());
        for b in TOKENS {
            out.push(format!("{a}{b}").into_bytes());
            for c in TOKENS {
                out.push(format!("{a}{b}{c}").into_bytes());
            }
        }
    }

    // 4. Random token soup, lengths 4..12.
    let mut rng = Rng(0x1234_5678_9abc_def0);
    for _ in 0..random_count / 2 {
        let n = 4 + rng.below(9);
        let mut s = String::new();
        for _ in 0..n {
            s.push_str(TOKENS[rng.below(TOKENS.len())]);
        }
        out.push(s.into_bytes());
    }

    // 5. Random raw bytes over a delimiter-heavy alphabet.
    let alphabet: Vec<u8> = b"abcXY019:/@?#.-_[]% \t\n\r+~\\!&=".to_vec();
    for _ in 0..random_count / 2 {
        let n = 1 + rng.below(24);
        let mut s = Vec::new();
        for _ in 0..n {
            if rng.below(8) == 0 {
                s.push((rng.below(255) + 1) as u8); // any non-NUL byte
            } else {
                s.push(alphabet[rng.below(alphabet.len())]);
            }
        }
        out.push(s);
    }

    out.sort();
    out.dedup();
    out
}

fn main() {
    let argv: Vec<String> = std::env::args().collect();
    let cpp = argv[1].clone();
    let rust = argv[2].clone();
    let random_count: usize = argv.get(3).map_or(20000, |s| s.parse().unwrap());

    let cases = corpus(random_count);
    let total = cases.len();
    println!("corpus: {total} cases");

    let next = AtomicUsize::new(0);
    let mismatches: Mutex<Vec<String>> = Mutex::new(Vec::new());
    let checked = AtomicUsize::new(0);
    let threads = std::thread::available_parallelism().map_or(4, |n| n.get());

    std::thread::scope(|scope| {
        for _ in 0..threads {
            scope.spawn(|| loop {
                let i = next.fetch_add(1, Ordering::Relaxed);
                if i >= total {
                    break;
                }
                let arg = &cases[i];
                let a = run(&cpp, arg);
                let b = run(&rust, arg);
                if a != b {
                    let mut m = mismatches.lock().unwrap();
                    if m.len() < 40 {
                        m.push(format!(
                            "INPUT  {}\n  cpp  out={:?} err={:?} exit={}\n  rust out={:?} err={:?} exit={}",
                            esc(arg),
                            esc(&a.0),
                            esc(&a.1),
                            a.2,
                            esc(&b.0),
                            esc(&b.1),
                            b.2
                        ));
                    }
                }
                let c = checked.fetch_add(1, Ordering::Relaxed) + 1;
                if c % 5000 == 0 {
                    println!("  .. {c}/{total}");
                }
            });
        }
    });

    let m = mismatches.into_inner().unwrap();
    println!("\nchecked {total} cases");
    if m.is_empty() {
        println!("RESULT: IDENTICAL on all {total} cases");
    } else {
        println!("RESULT: {} MISMATCH GROUP(S) (first 40 shown)", m.len());
        for line in &m {
            println!("{line}");
        }
        std::process::exit(1);
    }
}

